function u(t){if(!t)return NaN;let r=/(?:z|[+-]\d{2}:?\d{2})$/i.test(t);return new Date(r?t:`${t}Z`).getTime()}function s(t){let r=u(t);return Number.isNaN(r)?"":new Date(r).toLocaleString("en-GB",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:!1})}function f(t){let r=u(t);if(Number.isNaN(r))return"";let n=Math.floor((Date.now()-r)/1e3);if(n<0)return s(t);if(n<60)return"just now";let e=Math.floor(n/60);if(e<60)return`${e}m ago`;let a=Math.floor(e/60);if(a<24)return`${a}h ago`;let o=Math.floor(a/24);if(o<30)return`${o}d ago`;let i=Math.floor(o/30);return i<12?`${i}mo ago`:`${Math.floor(o/365)}y ago`}export{s as a,f as b};
